/* prog38_continued_fraction.c
 *
 * Reimplementation of the original obfuscated binary.
 * Behaviour:
 *   prog38_continued_fraction NUMERATOR DENOMINATOR
 *
 *   - Prints "NO_INPUT"   if fewer than two arguments are given.
 *   - Prints "BAD_INPUT"  if either argument is not a valid integer
 *                         or the denominator is zero.
 *   - Prints "OUT_OF_RANGE" if any term of the continued fraction
 *                         exceeds 100000 in absolute value.
 *   - Otherwise prints the continued‑fraction expansion in the form
 *       [a0; a1, a2, ... , ak]
 *     followed by a newline.
 *
 * The program never reads from stdin and always returns 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_TERM 100000   /* limit for each term of the expansion */

int main(int argc, char *argv[])
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse numerator ---------- */
    char *endptr;
    errno = 0;
    long num = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse denominator ---------- */
    errno = 0;
    long den = strtol(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- compute continued fraction ---------- */
    long terms[256];          /* sufficient for the ranges we handle */
    int nterms = 0;

    while (den != 0) {
        long q = num / den;          /* C truncates toward zero */
        long r = num % den;

        if (q > MAX_TERM || q < -MAX_TERM) {
            puts("OUT_OF_RANGE");
            return 0;
        }

        terms[nterms++] = q;

        /* prepare for next iteration */
        num = den;
        den = r;
    }

    /* ---------- output in the required format ---------- */
    putchar('[');
    if (nterms > 0) {
        printf("%ld", terms[0]);
    }

    if (nterms > 1) {
        /* first separator after a0 */
        printf("; %ld", terms[1]);
        for (int i = 2; i < nterms; ++i) {
            printf(", %ld", terms[i]);
        }
    }

    puts("]");
    return 0;
}
